/**
 *
 * DataTableTable is the table element inside the DataTable's scroll container.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTable
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableTable component.
 */
export type DataTableTablePassThroughType<E> = PassThroughType<DataTableTableInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTable component.
 */
export interface DataTableTablePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTablePassThroughType<React.HTMLAttributes<HTMLTableElement>>;
}
/**
 * Defines valid properties in DataTableTable component.
 */
export interface DataTableTableProps extends BaseComponentProps<DataTableTableInstance, unknown, DataTableTablePassThrough, 'table'> {
}
/**
 * Defines valid state in DataTableTable component.
 */
export interface DataTableTableState {
}
/**
 * Defines the methods and properties exposed by DataTableTable component.
 */
export interface DataTableTableExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTable component.
 */
export type DataTableTableInstance = ComponentInstance<DataTableTableProps, DataTableTableState, DataTableTableExposes>;
